mapper.select:
SELECT daily_seq AS dailySeq, deltakey, delta, jobid, name,
       daily_update AS dailyUpdate, userid, success
FROM h3_naver_delta
WHERE deltakey = #{deltakey}
  AND name     = #{name}
  AND userid   = #{userid}
LIMIT 1

SELECT COUNT(*) FROM h3_naver_delta
WHERE deltakey = #{deltakey}
  AND name     = #{name}
  AND userid   = #{userid}

mapper.update:
UPDATE h3_naver_delta
SET delta = #{delta}, daily_update = #{delta}, jobid = #{jobid}, success = 1
WHERE deltakey = #{deltakey}
  AND name     = #{name}
  AND userid   = #{userid}

UPDATE h3_naver_delta SET success = 0
WHERE deltakey = #{deltakey}
  AND name     = #{name}
  AND userid   = #{userid}
